      "explanation": "3 jenis keigo: (1) 尊敬語 (Sonkeigo) - meninggikan orang lain: お+masu-stem+になる (お読みになる) atau kata kerja khusus (いらっしゃる, おっしゃる). (2) 謙譲語 (Kenjougo) - merendahkan diri sendiri: お+masu-stem+する (お持ちする) atau kata kerja khusus (参る, 申す, いたす). (3) 丁寧語 (Teineigo) - bahasa sopan umum: 〜です/〜ます. Rumus konjugasi keigo: Sonkeigo = お〜になる / 〜(ら)れる. Kenjougo = お〜する / お〜いたす.",
